<?php
if(PHP_SAPI!=='cli'&&realpath($_SERVER['SCRIPT_FILENAME']??'')===realpath(__FILE__)){http_response_code(404);exit;}
require_once __DIR__.'/auth.php';require_once __DIR__.'/shu_helper.php';require_once __DIR__.'/shu_pinjaman_helper.php';
if(!isLoggedIn()||!isAdmin()){http_response_code(403);exit('Akses SHU hanya untuk Admin.');}
$view=$shuView??'periode';$page_title=['periode'=>'Dashboard SHU Pinjaman','anggota'=>'Pembayaran SHU','laporan'=>'Laporan SHU'][$view]??'SHU Pinjaman';
if(!shuPinjamanSiap($db)){http_response_code(503);exit('Modul SHU pinjaman memerlukan MIGRASI_UNIVERSAL.sql terbaru.');}
if($_SERVER['REQUEST_METHOD']==='POST'){$files=[];try{layananValidasiToken();$db->beginTransaction();$aksi=$_POST['aksi']??'';if($aksi==='sinkronkan'){$jumlah=shuSinkronkanHakLama($db);$_SESSION['success']='Sinkronisasi selesai. '.$jumlah.' pinjaman lunas diperiksa.';}elseif($aksi==='bayar'){$foto=validasiFotoUpload('bukti','Bukti pembayaran SHU',5*1024*1024,true);shuBayarHakPinjaman($db,(int)($_POST['hak_id']??0),$_POST['metode']??'',$_POST['referensi']??'',$foto,$files);$_SESSION['success']='Pembayaran SHU berhasil dicatat.';}else throw new Exception('Tindakan SHU tidak dikenal.');$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();foreach($files as $file)hapusFotoUpload($file);$_SESSION['error']=$e instanceof PDOException?'Data SHU gagal disimpan.':$e->getMessage();}header('Location: '.$_SERVER['PHP_SELF']);exit;}
$q=trim($_GET['q']??'');$status=$_GET['status']??'';$jenis=$_GET['jenis']??'';$where=['1=1'];$params=[];
if($q!==''){$where[]='(a.nama_lengkap LIKE ? OR a.kode_anggota LIKE ? OR p.kode_pinjaman LIKE ? OR s.nama_lengkap LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like);}if(in_array($status,['belum','sudah'],true)){$where[]='h.status_bayar=?';$params[]=$status;}if(in_array($jenis,['pelunasan','referensi'],true)){$where[]='h.jenis=?';$params[]=$jenis;}
$sql="SELECT h.*,p.kode_pinjaman,p.tanggal_lunas,a.nama_lengkap,a.kode_anggota,s.nama_lengkap sumber_nama,u.nama_lengkap admin_nama FROM shu_hak_pinjaman h JOIN pinjaman p ON p.id=h.pinjaman_id JOIN anggota a ON a.id=h.anggota_id JOIN anggota s ON s.id=h.sumber_anggota_id LEFT JOIN users u ON u.id=h.dibayar_oleh WHERE ".implode(' AND ',$where)." ORDER BY h.created_at DESC,h.id DESC";$stmt=$db->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);
$stats=$db->query("SELECT COUNT(*) jumlah,COALESCE(SUM(jumlah),0) total,COALESCE(SUM(status_bayar='sudah'),0) dibayar_jumlah,COALESCE(SUM(CASE WHEN status_bayar='sudah' THEN jumlah ELSE 0 END),0) dibayar,COALESCE(SUM(jenis='referensi'),0) referensi FROM shu_hak_pinjaman")->fetch(PDO::FETCH_ASSOC);
if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv;charset=UTF-8');header('Content-Disposition:attachment; filename="laporan-shu-pinjaman-'.date('Ymd').'.csv"');echo "\xEF\xBB\xBF";$o=fopen('php://output','w');fputcsv($o,['Pinjaman','Tanggal Lunas','Penerima','Sumber','Jenis','Kategori','Pokok','Persen','SHU','Lancar','Status','Dibayar']);foreach($rows as $r)fputcsv($o,[$r['kode_pinjaman'],$r['tanggal_lunas'],$r['nama_lengkap'],$r['sumber_nama'],$r['jenis'],$r['kategori_snapshot'],$r['dasar_pinjaman'],$r['persen'],$r['jumlah'],$r['pembayaran_lancar']?'Ya':'Tidak',$r['status_bayar'],$r['dibayar_at']]);fclose($o);exit;}
$rows_all=$rows;$ui_shu=ui_query_params(['status','jenis']);$pager=ui_paginate(count($rows_all),$ui_shu['page'],$ui_shu['per_page']);$rows=array_slice($rows_all,$pager['offset'],$pager['per_page']);
?>
