    'actions' => $view === 'laporan'
        ? '<a class="btn btn-sm btn-success" href="?' . http_build_query(array_merge($_GET, ['export' => 'csv'])) . '"><i class="fas fa-file-excel me-1"></i>Export CSV</a>'
        : '',
]); ?>
<?php ui_flash(); ?>
<div class="service-kpi-grid mb-4"><article class="service-kpi"><span>Total hak</span><strong><?= formatRupiah($stats['total']) ?></strong><small><?= (int)$stats['jumlah'] ?> catatan</small></article><article class="service-kpi"><span>Sudah dibayar</span><strong><?= formatRupiah($stats['dibayar']) ?></strong><small><?= (int)$stats['dibayar_jumlah'] ?> pembayaran</small></article><article class="service-kpi"><span>Belum dibayar</span><strong><?= formatRupiah($stats['total']-$stats['dibayar']) ?></strong><small>Menunggu pembayaran Admin</small></article><article class="service-kpi"><span>Bonus referensi</span><strong><?= (int)$stats['referensi'] ?></strong><small>Khusus anggota selalu tepat waktu</small></article></div>
<?php if($view==='periode'):?><section class="card mb-4"><div class="card-header"><h2 class="h5 mb-0">Aturan perhitungan aktif</h2></div><div class="card-body"><div class="row g-3"><div class="col-md-4"><strong>Anggota</strong><p class="mb-0 text-muted">1% × pokok pinjaman tanpa jaminan saat lunas.</p></div><div class="col-md-4"><strong>Ketua Kelompok</strong><p class="mb-0 text-muted">2% × pokok pinjaman pribadi tanpa jaminan saat lunas.</p></div><div class="col-md-4"><strong>Referensi Ketua</strong><p class="mb-0 text-muted">0,25% × pokok anggota yang diajak, hanya jika tidak pernah terlambat.</p></div></div><form method="post" class="mt-3"><?= layananToken() ?><input type="hidden" name="aksi" value="sinkronkan"><button class="btn btn-outline-primary"><i class="fas fa-sync me-1"></i>Sinkronkan pinjaman lunas lama</button></form></div></section><?php endif;?>
