<form method="get" class="row g-2 align-items-end mb-3"><div class="col-md-4"><label class="form-label">Cari penerima, sumber, atau kode pinjaman</label><input class="form-control" name="q" value="<?= layananEscape($q) ?>"></div><div class="col-md-2"><label class="form-label">Status</label><select class="form-select" name="status"><option value="">Semua</option><option value="belum" <?= $status==='belum'?'selected':'' ?>>Belum dibayar</option><option value="sudah" <?= $status==='sudah'?'selected':'' ?>>Sudah dibayar</option></select></div><div class="col-md-2"><label class="form-label">Jenis</label><select class="form-select" name="jenis"><option value="">Semua</option><option value="pelunasan" <?= $jenis==='pelunasan'?'selected':'' ?>>Pelunasan</option><option value="referensi" <?= $jenis==='referensi'?'selected':'' ?>>Referensi</option></select></div><div class="col-md-2"><label class="form-label">Per halaman</label><select class="form-select" name="per_page"><?php foreach([10,20,50] as $n):?><option value="<?= $n ?>" <?= (int)$pager['per_page']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach;?></select></div><div class="col-md-2 d-flex gap-2"><button class="btn btn-primary">Terapkan</button><a class="btn btn-outline-secondary" href="<?= layananEscape($_SERVER['PHP_SELF']) ?>">Reset</a></div></form>
<div class="table-responsive ui-table-scroll"><table class="table table-hover align-middle"><thead><tr><th>Pinjaman</th><th>Penerima</th><th>Sumber hak</th><th>Perhitungan</th><th>Nominal</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="text-center text-muted py-4">Belum ada hak SHU pinjaman.</td></tr><?php endif;foreach($rows as $r):?><tr><td><strong><?= layananEscape($r['kode_pinjaman']) ?></strong><br><small><?= !empty($r['tanggal_lunas'])?layananEscape(formatTanggalUi($r['tanggal_lunas'])):'—' ?></small></td><td><?= layananEscape($r['nama_lengkap']) ?><br><small><?= layananEscape($r['kode_anggota']) ?></small></td><td><?= $r['jenis']==='referensi'?'Referensi dari ':'Pelunasan pribadi' ?><?= $r['jenis']==='referensi'?'<br><small>'.layananEscape($r['sumber_nama']).'</small>':'' ?></td><td><?= formatRupiah($r['dasar_pinjaman']) ?> × <?= rtrim(rtrim(number_format($r['persen'],4,'.',''),'0'),'.') ?>%<br><small><?= $r['pembayaran_lancar']?'Pembayaran lancar':'Ada keterlambatan' ?></small></td><td><strong><?= formatRupiah($r['jumlah']) ?></strong></td><td><span class="badge <?= $r['status_bayar']==='sudah'?'bg-success':'bg-warning text-dark' ?>"><?= $r['status_bayar']==='sudah'?'Sudah dibayar':'Belum dibayar' ?></span><?php if($r['dibayar_at']):?><br><small><?= layananEscape(formatTanggalUi($r['dibayar_at'], true)) ?></small><?php endif;?></td><td class="table-actions"><?php if($r['status_bayar']==='belum'):?><button class="btn btn-sm btn-primary" data-bs-toggle="modal" data-bs-target="#pay<?= (int)$r['id'] ?>"><i class="fas fa-money-bill-wave me-1"></i>Bayar</button><?php else:?><a class="btn btn-sm btn-outline-primary" href="kwitansi_shu.php?id=<?= (int)$r['id'] ?>"><i class="fas fa-receipt me-1"></i>Kwitansi</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
